def E(ch, n, t, c, s): return _x("1ere-espagnol", LC, "Espagnol (LV2)", ch, n, t, c, s)
def ML(ch, n, t, c, s): return _x("1ere-maths-l", ["1ère L"], "Mathématiques", ch, n, t, c, s)
def MG(ch, n, t, c, s): return _x("1ere-maths-g", ["1ère G"], "Mathématiques", ch, n, t, c, s)
def EC(ch, n, t, c, s): return _x("g-eco", ["1ère G"], "Économie", ch, n, t, c, s)
